/**
 * Read-only local GCP onboarding and workspace-host preflight.
 *
 * Authentication is resolved through Application Default Credentials (ADC).
 * This module never creates, accepts, or stores service-account key material:
 * local users authenticate as themselves or use an impersonated-service-account
 * ADC file generated by gcloud. Provider calls use short-lived bearer tokens and
 * the same injected raw-REST seam as the existing Google Pub/Sub provisioner.
 */
import { execFile } from 'node:child_process';
import { promises as fs } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { createRequire } from 'node:module';
import { promisify } from 'node:util';
import type { CloudCredentialRef } from '@papercusp/deployment-driver';
import { describeFetchError } from '../loopback-fetch';

const requireCjs = createRequire(import.meta.url);
type ExecFileP = (
  file: string,
  args: string[],
  opts: Record<string, unknown>,
) => Promise<{ stdout: string; stderr: string }>;
let cachedExecFileP: ExecFileP | null = null;
function execFileP(
  file: string,
  args: string[],
  opts: Record<string, unknown>,
): Promise<{ stdout: string; stderr: string }> {
  if (!cachedExecFileP) cachedExecFileP = promisify(execFile) as unknown as ExecFileP;
  return cachedExecFileP(file, args, opts);
}

export const GCP_CLOUD_PLATFORM_SCOPE = 'https://www.googleapis.com/auth/cloud-platform';
/**
 * Resolve a short-lived token from the one active human gcloud account.
 *
 * This is deliberately explicit instead of silently falling back from ADC: a process may carry a
 * forbidden service-account key in GOOGLE_APPLICATION_CREDENTIALS while the operator selected the
 * human gcloud chain. The reference keeps that choice durable without persisting a bearer token.
 */
export const GCP_GCLOUD_ACTIVE_USER_CREDENTIAL_REF = 'gcloud://active-user';
export const GCP_WORKSPACE_HOST_REQUIRED_SERVICES = [
  'compute.googleapis.com',
  'iap.googleapis.com',
  'oslogin.googleapis.com',
] as const;

